# Decompose each demo's 3-cells into straight runs (maximal horizontal and vertical segments)
def runs(cells):
    hz=[]; vz=[]
    for p in sorted(cells):
        r,c=p
        hor=[(r,c)]
        while (r, c+1) in cells: c+=1; hor.append((r,c))
        vert=[(r,c)]
        while (r+1,c) in cells: r+=1; vert.append((r,c))
        if len(hor)>1: hz.append(hor)
        if len(vert)>1: vz.append(vert)
    return hz,vz
