import numpy as np, itertools
def arm_lengths(maxarm):
    for k in range(1,maxarm+1): yield k,k
def spiral(grid_in, seed, maxarm=5, startdir='U'):
    r,c=seed; out=set(); dirs={'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}[startdir]
    cur=[dirs[startdir]]; pos=[]
    for Ls in arm_lengths(maxarm):
        d=cur[-1]; 
        for _ in [0]*Ls: pass
        # simulate
        for seglen in Ls:
            dr_,dc_=d
            for s in range(seglen):
                rr,cc=r+dr_,c+dc_
                if not(0<=rr<11 and 0<=cc<11) or grid_in[rr][cc]==2: break
                r,c=rr,cc; out.add((r,c))
        # rotate clockwise each segment
        if len(cur)<=1: break
        rot={'U':'R','R':'D','D':'L','L':'U'}[cur[-1]]
        cur.append(dirs[rot])
    return out
for n,seed in [(3,(4,4)),(2,(5,5)),(1,(4,5))]:
