    true={(r,c) for r in range(11) for c in range(11) if o[r][c]==3}
    best=None
    for sdir in 'UDLR':
        for ma in range(1,7):
            sp=spiral(i,seed,ma,sdir)
            if sp==true: print(n,'MATCH',sdir,ma);break
            sc=len(sp&true)
            if best is None or sc>best[0]: best=(sc,sdir,ma)
    print('d',n,'argmax:',best)

