def comps(cells):
    seen=set(); out=[]
    for p in cells:
        if p in seen: continue
        stack=[p]; comp={p}
        while stack:
            cur=stack.pop()
            for q in [(cur[0]+1,cur[1]),(cur[0]-1,cur[1]),(cur[0],cur[1]+1),(cur[0],cur[1]-1)]:
                if q in cells and q not in comp: stack.append(q); comp.add(q)
        seen|=comp; out.append(comp)
    return out
